<?php
require_once __DIR__.'/_auth.php'; require_once __DIR__.'/../../../config/database.php';
$status=$_GET['status']??''; $ok=['pendente','aprovada','rejeitada'];
$sql="SELECT s.id_sugestao,s.nome_esporte,s.status_sugestao,s.data_sugestao,s.data_analise,u.nome_user,(SELECT COUNT(*) FROM Voto_Sugestao v WHERE v.id_sugestao=s.id_sugestao) votos FROM Sugestao_Esporte s INNER JOIN Usuario u ON u.id_user=s.id_user"; $p=[]; if(in_array($status,$ok,true)){ $sql.=' WHERE s.status_sugestao=?'; $p[]=$status;} $sql.=' ORDER BY (s.status_sugestao="pendente") DESC, votos DESC, s.data_sugestao DESC LIMIT 200'; $st=$conn->prepare($sql); $st->execute($p); $sug=$st->fetchAll(PDO::FETCH_ASSOC);
$paginaAdmin='sugestoes'; $tituloAdmin='Sugestões de esportes'; require __DIR__.'/includes/header.php';
?>
<form class="admin-filtros" method="get"><select name="status"><option value="">Todos os status</option><?php foreach($ok as $op): ?><option value="<?= $op ?>" <?= $status===$op?'selected':'' ?>><?= ucfirst($op) ?></option><?php endforeach; ?></select><button>Filtrar</button><a href="sugestoes.php">Limpar</a></form>
<div class="admin-sugestoes-grid"><?php if(!$sug): ?><p class="admin-vazio">Nenhuma sugestão encontrada.</p><?php endif; ?><?php foreach($sug as $s): ?><article class="admin-sugestao-card"><div class="admin-sugestao-top"><span class="admin-sugestao-votos"><b><?= (int)$s['votos'] ?></b> votos</span><span class="admin-status status-<?= htmlspecialchars($s['status_sugestao']) ?>"><?= htmlspecialchars($s['status_sugestao']) ?></span></div><p>SUGESTÃO #<?= (int)$s['id_sugestao'] ?></p><h2><?= htmlspecialchars($s['nome_esporte']) ?></h2><small>Enviada por <?= htmlspecialchars($s['nome_user']) ?> em <?= date('d/m/Y',strtotime($s['data_sugestao'])) ?></small><form class="admin-form-card" action="sugestao-acao.php" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['admin_csrf_token']) ?>"><input type="hidden" name="id_sugestao" value="<?= (int)$s['id_sugestao'] ?>"><select name="acao"><option value="aprovada">Aprovar e adicionar esporte</option><option value="rejeitada">Rejeitar</option><option value="pendente">Voltar para pendente</option></select><label>Foto do esporte (JPG, PNG ou WEBP, 4 MB) <input type="file" name="foto_esporte" accept="image/png,image/jpeg,image/webp"></label>
<label>Regras da modalidade <textarea name="regras_esporte" maxlength="2000" rows="3" placeholder="Regras para organizar partidas"></textarea></label>
<label>Jogadores por time <input type="number" name="jogadores_por_time" min="1" max="30" placeholder="Deixe em branco para esporte individual"></label>
<label>Quantidade de times <select name="quantidade_times"><option value="2">2 times</option><option value="1">1 equipe</option></select></label>
<label><input type="checkbox" name="exige_confirmacao_local" value="1" checked> Exigir confirmação do poliesportivo antes de usar esta modalidade</label>
<input name="motivo" maxlength="255" placeholder="Motivo da decisão" required><button>Salvar</button></form></article><?php endforeach; ?></div>
